import gurobipy as gp
from gurobipy import GRB
products = [rec['values'] for rec in LEGACY_RECORDS if rec['source'] == 'products.csv']
capacity_rec = next((rec for rec in LEGACY_RECORDS if rec['source'] == 'capacity.csv'))
vehicle_types = [p['ProductName'] for p in products]
benefit = {p['ProductName']: int(p['Value']) for p in products}
weight = {p['ProductName']: int(p['Weight']) for p in products}
capacity = int(capacity_rec['values']['Capacity'])
if not set(benefit) == set(vehicle_types) == set(weight):
    raise ValueError('Missing benefit or weight data for some vehicle types.')
m = gp.Model('Vehicle_Inventory_Optimization')
x = m.addVars(vehicle_types, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit[i] * x[i] for i in vehicle_types)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((weight[i] * x[i] for i in vehicle_types)) <= capacity, name='inventory_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')